class QueryBatcher {
    /**
     * @param {Function} queryMultiple
     * @param {number} t
     */
    constructor(queryMultiple, t) {
        this.queryMultiple = queryMultiple;
        this.t = t;
        this.pending = [];       // [{ key, resolve }] waiting for the next query
        this.inWindow = false;   // true while a throttle window of t ms is running
    }

    /**
     * @param {string} key
     * @return {Promise<string>}
     */
    async getValue(key) {
        return new Promise((resolve) => {
            this.pending.push({ key, resolve });
            if (!this.inWindow) this.flush();  // first call after a quiet period runs immediately
        });
    }

    flush() {
        const batch = this.pending;
        this.pending = [];
        this.inWindow = true;

        // One query for the whole batch; its own latency doesn't extend the window
        this.queryMultiple(batch.map((p) => p.key)).then((values) => {
            batch.forEach((p, i) => p.resolve(values[i]));
        });

        // After t ms: send whatever was queued meanwhile (this opens a new window)
        setTimeout(() => {
            this.inWindow = false;
            if (this.pending.length > 0) this.flush();
        }, this.t);
    }
}

